const request = $json.body ?? $json;
const uuid = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
const key = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;
const correlation = typeof request?.correlation_id === 'string' ? request.correlation_id : 'unavailable';
const fail = (message) => [{ json: { valid: false, response: { ok: false, correlation_id: correlation, error: { code: 'INVALID_REQUEST', message } } } }];
const isObject = (value) => value && typeof value === 'object' && !Array.isArray(value);
const nonBlank = (value) => typeof value === 'string' && value.trim() !== '';
const initialMemoryTypes = new Set(['event', 'emotion', 'knowledge', 'relationship']);
const initialMemoryTruthStatuses = new Set(['true', 'misremembered', 'false']);
const ids = (value) => Array.isArray(value) && value.every((item) => typeof item === 'string' && uuid.test(item));
const candidateValid = (candidate) => {
  if (!isObject(candidate) || !Array.isArray(candidate.characters) || !candidate.characters.length || !Array.isArray(candidate.relations) || !Array.isArray(candidate.initial_memories)) return false;
  const refs = new Set();
  const types = new Set(['protagonist', 'supporting', 'ensemble', 'antagonist']);
  for (const character of candidate.characters) {
    if (!isObject(character) || !nonBlank(character.client_ref) || refs.has(character.client_ref) || !nonBlank(character.char_name) || !types.has(character.char_type) || !isObject(character.five_layers_json) || !['L0', 'L1', 'L2', 'L3'].every((layer) => isObject(character.five_layers_json[layer])) || !isObject(character.knowledge_boundary_json) || !['knows', 'unknown', 'false_belief', 'reasonable_suspect'].every((field) => Array.isArray(character.knowledge_boundary_json[field])) || !isObject(character.arc_json)) return false;
    refs.add(character.client_ref);
  }
  const signed = ['trust', 'intimacy', 'power_balance', 'dependence', 'emotional_bond'];
  const percentage = ['hostility', 'common_goal', 'secret_known'];
  return candidate.relations.every((relation) => isObject(relation) && refs.has(relation.from_ref) && refs.has(relation.to_ref) && relation.from_ref !== relation.to_ref && nonBlank(relation.relation_type) && nonBlank(relation.relation_hierarchy) && signed.every((field) => Number.isInteger(relation[field]) && relation[field] >= -100 && relation[field] <= 100) && percentage.every((field) => Number.isInteger(relation[field]) && relation[field] >= 0 && relation[field] <= 100) && isObject(relation.change_event_json) && ['description', 'event', 'summary'].some((field) => nonBlank(relation.change_event_json[field]))) && candidate.initial_memories.every((memory) => isObject(memory) && refs.has(memory.char_ref) && initialMemoryTypes.has(memory.memory_type) && initialMemoryTruthStatuses.has(memory.truth_status) && nonBlank(memory.memory_content));
};
if (!isObject(request) || !uuid.test(request.local_operator_id ?? '') || !uuid.test(request.book_id ?? '') || !key.test(request.correlation_id ?? '')) return fail('The request identifiers are invalid.');
if (request.action === 'generate_candidate' || request.action === 'read_versions') {
  const allowed = new Set(['action', 'correlation_id', 'local_operator_id', 'book_id']);
  if (Object.keys(request).some((field) => !allowed.has(field))) return fail('This request accepts only the request identifiers.');
  return [{ json: { valid: true, request } }];
}
if (request.action === 'save_candidate') {
  const allowed = new Set(['action', 'correlation_id', 'local_operator_id', 'book_id', 'candidate', 'bindings']);
  if (!candidateValid(request.candidate) || !Array.isArray(request.bindings) || request.bindings.length || Object.keys(request).some((field) => !allowed.has(field))) return fail('Candidate saving requires complete character and relation candidates; bindings need a stable selectable world source.');
  return [{ json: { valid: true, request } }];
}
if (request.action === 'confirm') {
  const allowed = new Set(['action', 'correlation_id', 'local_operator_id', 'book_id', 'idempotency_key', 'character_candidate_ids', 'relation_candidate_ids', 'binding_candidate_ids', 'initial_memories']);
  const memories = request.initial_memories;
  const memoriesValid = memories === undefined || (Array.isArray(memories) && memories.every((memory) => isObject(memory) && uuid.test(memory.char_id ?? '') && initialMemoryTypes.has(memory.memory_type) && initialMemoryTruthStatuses.has(memory.truth_status) && nonBlank(memory.memory_content)));
  if (!key.test(request.idempotency_key ?? '') || !Array.isArray(request.character_candidate_ids) || !request.character_candidate_ids.length || !ids(request.character_candidate_ids) || (request.relation_candidate_ids !== undefined && !ids(request.relation_candidate_ids)) || (request.binding_candidate_ids !== undefined && !ids(request.binding_candidate_ids)) || !memoriesValid || Object.keys(request).some((field) => !allowed.has(field))) return fail('Confirmation must provide stable candidate IDs and an idempotency key.');
  const rpc_request = { local_operator_id: request.local_operator_id, book_id: request.book_id, idempotency_key: request.idempotency_key, character_candidate_ids: request.character_candidate_ids, ...(request.relation_candidate_ids === undefined ? {} : { relation_candidate_ids: request.relation_candidate_ids }), ...(request.binding_candidate_ids === undefined ? {} : { binding_candidate_ids: request.binding_candidate_ids }), ...(request.initial_memories === undefined ? {} : { initial_memories: request.initial_memories }) };
  return [{ json: { valid: true, request, rpc_request } }];
}
return fail('Unsupported character settings action.');

const request = $('Validate Character Command').first().json.request;
const context = $json.context ?? {};
const runtime = context.runtime ?? {};
const fail = (code, message) => [{ json: { valid: false, response: { ok: false, correlation_id: request?.correlation_id ?? 'unavailable', error: { code, message } } } }];
if (context.book_exists !== true) return fail('SCOPE_REJECTED', 'The selected book is unavailable.');
if (context.design_editable !== true) return fail('DESIGN_LOCKED', 'Character settings are read-only after L1A sorting is confirmed.');
const configured = typeof runtime.model_name === 'string' && runtime.model_name.trim() !== ''
  && typeof runtime.provider_base_url === 'string' && runtime.provider_base_url.trim() !== ''
  && typeof runtime.prompt_text === 'string' && runtime.prompt_text.trim() !== ''
  && typeof runtime.api_key_ref === 'string' && runtime.api_key_ref.trim() !== '';
if (!configured) return fail('CONFIG_CONTRACT_BLOCKED', 'An active FP003-04 model and prompt binding is required.');
return [{ json: { valid: true, request, runtime, context } }];

const request = $('Require Active Model Binding').first().json.request;
const text = $json.output_text ?? $json.output?.[0]?.content?.[0]?.text ?? $json.message?.content ?? $json.content ?? $json.text;
const fail = () => [{ json: { response: { ok: false, correlation_id: request?.correlation_id ?? 'unavailable', error: { code: 'INTERNAL_ERROR', message: '角色候选格式不完整，请重新生成。' } } } }];
const isObject = (value) => value && typeof value === 'object' && !Array.isArray(value);
const nonBlank = (value) => typeof value === 'string' && value.trim() !== '';
const characterTypes = new Set(['protagonist', 'supporting', 'ensemble', 'antagonist']);
const initialMemoryTypes = new Set(['event', 'emotion', 'knowledge', 'relationship']);
const initialMemoryTruthStatuses = new Set(['true', 'misremembered', 'false']);
const signedDimensions = ['trust', 'intimacy', 'power_balance', 'dependence', 'emotional_bond'];
const percentageDimensions = ['hostility', 'common_goal', 'secret_known'];
try {
  const candidate = JSON.parse(text);
  const arrays = ['characters', 'relations', 'initial_memories'];
  if (!isObject(candidate) || !arrays.every((key) => Array.isArray(candidate[key])) || candidate.characters.length === 0) throw new Error('shape');
  const refs = new Set();
  for (const character of candidate.characters) {
    if (!isObject(character) || !nonBlank(character.client_ref) || refs.has(character.client_ref) || !nonBlank(character.char_name) || !characterTypes.has(character.char_type) || !isObject(character.five_layers_json) || !['L0', 'L1', 'L2', 'L3'].every((key) => isObject(character.five_layers_json[key])) || !isObject(character.knowledge_boundary_json) || !['knows', 'unknown', 'false_belief', 'reasonable_suspect'].every((key) => Array.isArray(character.knowledge_boundary_json[key])) || !isObject(character.arc_json) || (character.gender !== undefined && typeof character.gender !== 'string')) throw new Error('character');
    refs.add(character.client_ref);
  }
  const relations = [];
  const relationPairs = new Set();
  for (const relation of candidate.relations) {
    if (!isObject(relation) || !refs.has(relation.from_ref) || !refs.has(relation.to_ref) || relation.from_ref === relation.to_ref || !nonBlank(relation.relation_type) || !nonBlank(relation.relation_hierarchy) || !signedDimensions.every((key) => Number.isInteger(relation[key]) && relation[key] >= -100 && relation[key] <= 100) || !percentageDimensions.every((key) => Number.isInteger(relation[key]) && relation[key] >= 0 && relation[key] <= 100)) throw new Error('relation');
    const pairKey = JSON.stringify([relation.from_ref, relation.to_ref].sort());
    if (relationPairs.has(pairKey)) throw new Error('relation_duplicate_pair');
    relationPairs.add(pairKey);
    const eventInput = relation.change_event_json ?? relation.change_event;
    const changeEvent = typeof eventInput === 'string' && eventInput.trim() ? { event: eventInput.trim() } : eventInput;
    if (!isObject(changeEvent) || !['description', 'event', 'summary'].some((key) => nonBlank(changeEvent[key]))) throw new Error('relation_event');
    const normalized = { ...relation, change_event_json: changeEvent };
    delete normalized.change_event;
    relations.push(normalized);
  }
  for (const memory of candidate.initial_memories) {
    if (!isObject(memory) || !refs.has(memory.char_ref) || !initialMemoryTypes.has(memory.memory_type) || !initialMemoryTruthStatuses.has(memory.truth_status) || !nonBlank(memory.memory_content)) throw new Error('memory');
  }
  const normalizedCandidate = { ...candidate, relations };
  return [{ json: { response: { ok: true, correlation_id: request.correlation_id, result: { status: 'candidate', candidate: normalizedCandidate } } } }];
} catch {
  return fail();
}
